use crate::domain::card::CardId;
use uuid::Uuid;

/// Identifies a scan batch: generated by the client when it creates the batch, kept until a
/// validation succeeds. It is the idempotence key of the validation.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct ScanBatchId(pub Uuid);

/// A line of a scan batch as the client sent it: the quantity is not checked yet.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ScanBatchLine {
    pub card_id: CardId,
    pub foil: bool,
    pub quantity: i32,
}

/// A line of a scan batch ready to be written: its card exists and its quantity is in bounds.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ScanBatchCopies {
    pub card_id: CardId,
    pub foil: bool,
    pub quantity: u8,
}

/// What a validation of a scan batch answers.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ScanBatchOutcome {
    /// Copies the batch holds, whether this call wrote them or the first one did.
    pub copies_added: u32,
    /// `true` when the batch had been validated already, so this call wrote nothing.
    pub already_validated: bool,
}
